package com.railflow.yardops.config;
import com.railflow.yardops.domain.*; import com.railflow.yardops.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import java.time.*;
@Configuration public class DataInitializer { @Bean CommandLineRunner seed(ShipmentRepository s,RailcarRepository c,TrainRepository t,YardRepository y,AlertRepository a){return args->{if(y.count()>0)return; y.save(new Yard("NPT","North Platte Hub","North Platte, NE",42,31)); y.save(new Yard("KCM","Kansas City Terminal","Kansas City, KS",28,20)); c.save(new Railcar("BNSF-48219","Covered hopper",2860,"NPT","Grain",RailcarStatus.IN_YARD)); c.save(new Railcar("BNSF-77104","Boxcar",2860,"KCM","Paper",RailcarStatus.IN_TRANSIT)); s.save(new Shipment("RF-24081","North Platte","Kansas City","Wheat","Prairie Grain Co.","HIGH")); s.save(new Shipment("RF-24082","Lincoln","Chicago","Paper","Midwest Paper","NORMAL")); t.save(new Train("M-KCMCHI-26","North Platte","Chicago",Instant.now().minusSeconds(3600),Instant.now().plusSeconds(28800),"IN_TRANSIT")); a.save(new OperationalAlert("EXCESSIVE_DWELL","BNSF-48219 has been in North Platte for 31 hours","BNSF-48219",AlertSeverity.WARNING));};} }